ALTER POLICY gallery_public_read_concours_sponsor_logos ON storage.objects USING (bucket_id = 'gallery' AND EXISTS (SELECT 1 FROM public.event_concours c JOIN public.events e ON e.id = c.event_id WHERE c.enabled = true AND e.is_published = true AND right(split_part(c.sponsor_logo_url, '?', 1), length('/storage/v1/object/public/gallery/' || objects.name)) = '/storage/v1/object/public/gallery/' || objects.name));